import heapq


def stockQueries(ops):
    price = {}
    hi, lo = [], []
    latest = 0
    out = []
    for t, a, b in ops:
        if t == 1:
            price[a] = b
            if a > latest:
                latest = a
            heapq.heappush(hi, (-b, a))
            heapq.heappush(lo, (b, a))
        elif t == 2:
            out.append(price[latest])
        elif t == 3:
            while price[hi[0][1]] != -hi[0][0]:
                heapq.heappop(hi)
            out.append(-hi[0][0])
        else:
            while price[lo[0][1]] != lo[0][0]:
                heapq.heappop(lo)
            out.append(lo[0][0])
    return out
